-- Migration 0014: Expand chip_family for ESP8266 and seed Waveshare ESP32-S3-Zero & NodeMCU ESP8266

DO $$ DECLARE c RECORD; BEGIN
  FOR c IN SELECT conname FROM pg_constraint WHERE conrelid = 'public.board_catalog'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) LIKE '%chip_family%' LOOP
    EXECUTE format('ALTER TABLE public.board_catalog DROP CONSTRAINT %I', c.conname);
  END LOOP;
  FOR c IN SELECT conname FROM pg_constraint WHERE conrelid = 'public.custom_boards'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) LIKE '%chip_family%' LOOP
    EXECUTE format('ALTER TABLE public.custom_boards DROP CONSTRAINT %I', c.conname);
  END LOOP;
  FOR c IN SELECT conname FROM pg_constraint WHERE conrelid = 'public.firmware_releases'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) LIKE '%chip_family%' LOOP
    EXECUTE format('ALTER TABLE public.firmware_releases DROP CONSTRAINT %I', c.conname);
  END LOOP;
END $$;

ALTER TABLE public.board_catalog ADD CONSTRAINT board_catalog_chip_family_check CHECK (chip_family IN ('esp32', 'esp32s2', 'esp32s3', 'esp32s31', 'esp32c2', 'esp32c3', 'esp32c5', 'esp32c6', 'esp32c61', 'esp32h2', 'esp32h21', 'esp32h4', 'esp32p4', 'esp8266'));
ALTER TABLE public.custom_boards ADD CONSTRAINT custom_boards_chip_family_check CHECK (chip_family IN ('esp32', 'esp32s2', 'esp32s3', 'esp32s31', 'esp32c2', 'esp32c3', 'esp32c5', 'esp32c6', 'esp32c61', 'esp32h2', 'esp32h21', 'esp32h4', 'esp32p4', 'esp8266'));
ALTER TABLE public.firmware_releases ADD CONSTRAINT firmware_releases_chip_family_check CHECK (chip_family IN ('esp32', 'esp32s2', 'esp32s3', 'esp32s31', 'esp32c2', 'esp32c3', 'esp32c5', 'esp32c6', 'esp32c61', 'esp32h2', 'esp32h21', 'esp32h4', 'esp32p4', 'esp8266'));

